CREATE TABLE public.referral_board_consent(user_id uuid PRIMARY KEY REFERENCES public.profiles(id), display_name text NOT NULL DEFAULT '', region text NOT NULL DEFAULT '' CHECK(region IN('','AP','TG')), published boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE ON public.referral_board_consent TO authenticated; GRANT ALL ON public.referral_board_consent TO service_role;
ALTER TABLE public.referral_board_consent ENABLE ROW LEVEL SECURITY;
CREATE POLICY consent_owner ON public.referral_board_consent FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.public_referral_vip_board() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH configuration AS (SELECT CASE WHEN now()<coalesce((SELECT started_at FROM public.referral_vip_campaign WHERE id),now())+interval '15 days' THEN 10 WHEN now()<coalesce((SELECT started_at FROM public.referral_vip_campaign WHERE id),now())+interval '30 days' THEN 25 ELSE 50 END AS places), ranked AS (SELECT r.user_id,r.joins,row_number() OVER(ORDER BY r.joins DESC,r.rank_no) AS place,c.display_name,c.published,c.region FROM public.referral_vip_ranks() r JOIN public.referral_board_consent c ON c.user_id=r.user_id WHERE c.region IN('AP','TG')) SELECT jsonb_build_object('limit',(SELECT places FROM configuration),'event_label',coalesce((SELECT event_label FROM public.referral_vip_campaign WHERE id),'డిసెంబర్ 31'),'details_at',(SELECT details_at FROM public.referral_vip_campaign WHERE id),'rows',coalesce((SELECT jsonb_agg(jsonb_build_object('rank',place,'count',joins,'name',CASE WHEN published THEN display_name ELSE '' END,'region',region) ORDER BY place) FROM ranked WHERE place<=(SELECT places FROM configuration)),'[]'::jsonb)) $$;
REVOKE ALL ON FUNCTION public.public_referral_vip_board() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_referral_vip_board() TO anon,authenticated;
CREATE FUNCTION public.configure_referral_event(_label text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; IF length(trim(_label))<1 OR length(_label)>80 THEN RAISE EXCEPTION 'INVALID_EVENT'; END IF; INSERT INTO public.referral_vip_campaign(id,event_label) VALUES(true,trim(_label)) ON CONFLICT(id) DO UPDATE SET event_label=excluded.event_label; END $$;
REVOKE ALL ON FUNCTION public.configure_referral_event(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.configure_referral_event(text) TO authenticated;